def transform(grid):
    h,w=len(grid),len(grid[0])
    seen=set(); objs=[]
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if not color or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
          y,x=q.pop(); cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
              seen.add((yy,xx)); q.append((yy,xx))
        miny=min(y for y,x in cells); maxy=max(y for y,x in cells); minx=min(x for y,x in cells); maxx=max(x for y,x in cells)
        # Detect enclosed empty cells inside the object's bounding box.
        zeros={(y,x) for y in range(miny,maxy+1) for x in range(minx,maxx+1) if grid[y][x]==0}
        exterior=set(); qq=[]
        for y,x in zeros:
          if y in (miny,maxy) or x in (minx,maxx): exterior.add((y,x)); qq.append((y,x))
        while qq:
          y,x=qq.pop()
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if (yy,xx) in zeros and (yy,xx) not in exterior: exterior.add((yy,xx)); qq.append((yy,xx))
        hollow=bool(zeros-exterior)
        objs.append(dict(color=color,cells=cells,y=miny,x=minx,hollow=hollow))
    out=[[0]*w for _ in range(h)]
    placed={True:[],False:[]}
    # Place hollow objects toward top, open objects toward bottom; keep original order within each direction.
    for hollow, order in ((True,sorted((o for o in objs if o['hollow']),key=lambda o:o['y'])), (False,sorted((o for o in objs if not o['hollow']),key=lambda o:o['y'],reverse=True))):
      for o in order:
        cells=o['cells']; dy=0
        while True:
          step=-1 if hollow else 1
          moved=[(y+dy+step,x) for y,x in cells]
          if any(y<0 or y>=h for y,x in moved): break
          if any(any((y,x) in set((yy+ddy,xx) for yy,xx in p['cells']) for p in placed[hollow]) for y,x in moved): break
          dy+=step
        for y,x in cells:
          yy=y+dy; out[yy][x]=o['color']
        placed[hollow].append({**o,'dy':dy})
    return out

